"use client";

import { FormEvent, useCallback, useEffect, useMemo, useState } from "react";
import { Bar, BarChart, CartesianGrid, Cell, Legend, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";

type Pick = { id: string; name: string };
type Component = { id: string; code: string; label: string; maximum_score: number; weight: number; precision_digits: number; is_developmental: boolean; counts_toward_total: boolean; sort_order: number };
type Pupil = { id: string; admission_number: string; first_name: string; middle_name?: string | null; last_name: string };
const money = (amount: unknown) => new Intl.NumberFormat("en-NG", { style: "currency", currency: "NGN", maximumFractionDigits: 2 }).format(Number(amount || 0));
const shortMonth = (month: string) => new Date(`${month}-01T00:00:00Z`).toLocaleDateString("en-NG", { month: "short", year: "2-digit", timeZone: "UTC" });

export function ScoresWorkspace({ division, permissions }: { division: string; permissions: string[] }) {
  const [filters, setFilters] = useState({ classId: "", subjectId: "", sessionId: "", termId: "" });
  const [options, setOptions] = useState<{ classes: (Pick & { sort_order: number })[]; subjects: (Pick & { code: string })[]; sessions: (Pick & { is_current: boolean })[]; terms: (Pick & { session_id: string; is_current: boolean })[] }>({ classes: [], subjects: [], sessions: [], terms: [] });
  const [students, setStudents] = useState<Pupil[]>([]);
  const [components, setComponents] = useState<Component[]>([]);
  const [scores, setScores] = useState<{ student_id: string; component_id: string; numeric_score: number | null; developmental_level: string | null; score_state: string }[]>([]);
  const [bands, setBands] = useState<{ grade_code: string; label: string; minimum_score: number; maximum_score: number; remark: string | null }[]>([]);
  const [batch, setBatch] = useState<{ id: string; status: string; version: number } | null>(null);
  const [drafts, setDrafts] = useState<Record<string, { state: "PRESENT" | "ABSENT" | "MISSING"; score: string; development: string }>>({});
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [note, setNote] = useState("");

  const query = useMemo(() => new URLSearchParams({ division, ...filters }).toString(), [division, filters]);
  const load = useCallback(async () => {
    setError("");
    const response = await fetch(`/api/portal/scores?${query}`, { cache: "no-store" });
    const data = await response.json();
    if (!response.ok) { setError(data.error ?? "Score sheet unavailable."); return; }
    setOptions({ classes: data.classes ?? [], subjects: data.subjects ?? [], sessions: data.sessions ?? [], terms: data.terms ?? [] });
    setStudents(data.students ?? []); setComponents(data.components ?? []); setScores(data.scores ?? []); setBands(data.grades ?? []); setBatch(data.batch ?? null);
    setDrafts((old) => {
      const next = { ...old };
      for (const student of data.students ?? []) for (const component of data.components ?? []) {
        const key = `${student.id}:${component.id}`;
        if (!next[key]) {
          const score = (data.scores ?? []).find((row: { student_id: string; component_id: string }) => row.student_id === student.id && row.component_id === component.id);
          next[key] = { state: score?.score_state ?? "MISSING", score: score?.numeric_score == null ? "" : String(score.numeric_score), development: score?.developmental_level ?? "" };
        }
      }
      return next;
    });
  }, [query]);
  useEffect(() => { load(); }, [load]);
  useEffect(() => {
    if (!filters.classId && options.classes.length) setFilters((f) => ({ ...f, classId: options.classes[0].id }));
    if (!filters.subjectId && options.subjects.length) setFilters((f) => ({ ...f, subjectId: options.subjects[0].id }));
    if (!filters.sessionId && options.sessions.length) setFilters((f) => ({ ...f, sessionId: options.sessions.find((s) => s.is_current)?.id ?? options.sessions[0].id }));
    if (filters.sessionId && !filters.termId) {
      const sessionTerms = options.terms.filter((term) => term.session_id === filters.sessionId);
      if (sessionTerms.length) setFilters((f) => ({ ...f, termId: sessionTerms.find((t) => t.is_current)?.id ?? sessionTerms[0].id }));
    }
  }, [options, filters]);

  const rowTotals = useMemo(() => students.map((student) => {
    let numerator = 0; let denominator = 0;
    for (const component of components) {
      if (!component.counts_toward_total) continue;
      const key = `${student.id}:${component.id}`;
      const stored = scores.find((row) => row.student_id === student.id && row.component_id === component.id);
      const draft = drafts[key];
      const state = draft?.state ?? stored?.score_state ?? "MISSING";
      if (state !== "PRESENT") continue;
      denominator += Number(component.weight);
      const value = component.is_developmental ? null : Number(draft?.score ?? stored?.numeric_score ?? 0);
      if (value !== null && Number.isFinite(value)) numerator += (value / Number(component.maximum_score)) * Number(component.weight);
    }
    return { id: student.id, total: denominator ? Math.round(numerator / denominator * 10000) / 100 : null };
  }), [students, components, scores, drafts]);
  const ranked = useMemo(() => { const sorted = [...rowTotals].filter((r) => r.total !== null).sort((a, b) => (b.total ?? 0) - (a.total ?? 0)); let lastTotal: number | null = null; let rank = 0; return sorted.map((row,index) => { if (index === 0 || row.total !== lastTotal) rank = index + 1; lastTotal = row.total; return { ...row, position: rank }; }); }, [rowTotals]);
  const editable = !batch || ["DRAFT", "CORRECTION_REQUESTED"].includes(batch.status);
  const canReview = permissions.includes("results.review"); const canPublish = permissions.includes("results.publish");
  function updateCell(studentId: string, componentId: string, patch: Partial<{ state: "PRESENT" | "ABSENT" | "MISSING"; score: string; development: string }>) {
    const key = `${studentId}:${componentId}`;
    setDrafts((old) => ({ ...old, [key]: { state: old[key]?.state ?? "MISSING", score: old[key]?.score ?? "", development: old[key]?.development ?? "", ...patch } }));
  }
  async function send(action: "SAVE" | "SUBMIT" | "REVIEW" | "APPROVE" | "PUBLISH" | "REQUEST_CORRECTION" | "APPROVE_CORRECTION") {
    if (!filters.classId || !filters.subjectId || !filters.sessionId || !filters.termId) { setError("Choose class, subject, session and term first."); return; }
    setBusy(true); setError(""); setNotice("");
    let body: Record<string, unknown>;
    if (action === "SAVE") {
      const rows = students.flatMap((student) => components.map((component) => {
        const cell = drafts[`${student.id}:${component.id}`] ?? { state: "MISSING", score: "", development: "" };
        return { student_id: student.id, component_id: component.id, score_state: cell.state, numeric_score: cell.state === "PRESENT" && !component.is_developmental && cell.score !== "" ? Number(cell.score) : null, developmental_level: cell.state === "PRESENT" && component.is_developmental ? cell.development || null : null };
      }));
      body = { action, division, ...filters, batchId: batch?.id, rows };
    } else body = { action, division, batchId: batch?.id, note };
    const response = await fetch("/api/portal/scores", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
    const result = await response.json(); setBusy(false);
    if (!response.ok) { setError(result.error ?? "The score workflow failed."); return; }
    if (action === "SAVE") setNotice(`${result.savedRows} pupil-component marks saved. Scores remain in draft.`);
    else setNotice(`Score batch is now ${String(result.status).replaceAll("_", " ")}.`);
    await load();
  }
  function downloadCsv() {
    const header = ["Admission number", "Pupil", ...components.map((c) => `${c.label} (${c.maximum_score})`), "Weighted total / 100", "Subject position"];
    const lines = [header, ...students.map((student) => { const total = ranked.find((r) => r.id === student.id); return [student.admission_number, [student.first_name, student.middle_name, student.last_name].filter(Boolean).join(" "), ...components.map((c) => { const cell = drafts[`${student.id}:${c.id}`]; return cell?.state === "ABSENT" ? "ABSENT" : cell?.state === "MISSING" ? "MISSING" : c.is_developmental ? cell?.development : cell?.score; }), total?.total ?? "", total?.position ?? ""]; })];
    const csv = lines.map((line) => line.map((cell) => `"${String(cell ?? "").replaceAll('"', '""')}"`).join(",")).join("\r\n");
    const link = document.createElement("a"); link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); link.download = "upwa-subject-broadsheet.csv"; link.click(); URL.revokeObjectURL(link.href);
  }
  return <div className="space-y-5"><section className="rounded-2xl border border-slate-200 bg-white p-5"><h1 className="text-lg font-bold text-upwa-navy">Teacher scores, broadsheets and approvals</h1><p className="mt-1 text-sm text-slate-600">Enter marks by class. Maximums and decimal precision come from the authorised component setup. Weighted total is normalised to 100; only published scores appear in the family Results Centre.</p><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{([ ["classId","Class",options.classes], ["subjectId","Subject",options.subjects], ["sessionId","Session",options.sessions], ["termId","Term",options.terms.filter((t) => t.session_id === filters.sessionId)] ] as [keyof typeof filters,string,Pick[]][]).map(([key,label,choices]) => <label key={key} className="text-xs font-semibold text-slate-600">{label}<select value={filters[key]} onChange={(e) => setFilters((f) => ({ ...f, [key]: e.target.value, ...(key === "sessionId" ? { termId: "" } : {}) }))} className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"><option value="">Select {label.toLowerCase()}</option>{choices.map((choice) => <option key={choice.id} value={choice.id}>{choice.name}</option>)}</select></label>)}</div>{batch && <p className="mt-3 text-xs font-semibold text-slate-600">Batch {batch.status.replaceAll("_"," ")} · version {batch.version}</p>}{error && <p role="alert" className="mt-3 text-sm text-rose-700">{error}</p>}{notice && <p role="status" className="mt-3 text-sm text-upwa-green-800">{notice}</p>}</section>
    {components.length === 0 ? <section className="rounded-xl border border-upwa-orange-200 bg-upwa-orange-50 p-4 text-sm text-upwa-orange-900">No assessment components are configured for this division. An authorised officer must define component labels, maximums, weights and decimal precision before marks can be entered.</section> : <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white"><div className="flex flex-wrap items-center justify-between gap-3 border-b p-4"><div><h2 className="font-bold text-upwa-navy">Class score sheet</h2><p className="text-xs text-slate-500">ABSENT and MISSING are distinct states; they are excluded from the weighted average.</p></div><div className="flex flex-wrap gap-2"><button onClick={downloadCsv} className="rounded-lg border px-3 py-2 text-xs font-semibold">Export CSV</button><button onClick={() => window.print()} className="rounded-lg border px-3 py-2 text-xs font-semibold">Print broadsheet</button>{editable && <button disabled={busy} onClick={() => send("SAVE")} className="rounded-lg bg-upwa-blue-700 px-3 py-2 text-xs font-semibold text-white">{busy ? "Saving…" : "Save draft"}</button>}{editable && batch && <button disabled={busy} onClick={() => send("SUBMIT")} className="rounded-lg bg-upwa-green-700 px-3 py-2 text-xs font-semibold text-white">Submit for review</button>}</div></div><div className="overflow-x-auto"><table className="min-w-full border-collapse text-left text-xs"><thead className="bg-slate-50"><tr><th className="sticky left-0 min-w-52 bg-slate-50 p-3">Pupil</th>{components.map((component) => <th key={component.id} className="min-w-40 p-3">{component.label}<span className="block font-normal text-slate-500">max {component.maximum_score} · wt {component.weight}</span></th>)}<th className="min-w-28 p-3">Weighted %</th><th className="p-3">Position</th><th className="p-3">Grade</th></tr></thead><tbody>{students.map((student) => { const total = ranked.find((r) => r.id === student.id); const grade = bands.find((b) => total?.total != null && total.total >= Number(b.minimum_score) && total.total <= Number(b.maximum_score)); return <tr key={student.id} className="border-t border-slate-100"><td className="sticky left-0 bg-white p-3"><b>{student.last_name}, {student.first_name}</b><span className="mt-1 block font-mono text-slate-500">{student.admission_number}</span></td>{components.map((component) => { const key = `${student.id}:${component.id}`; const cell = drafts[key] ?? { state: "MISSING" as const, score: "", development: "" }; return <td key={component.id} className="p-2"><select disabled={!editable} value={cell.state} onChange={(e) => updateCell(student.id,component.id,{ state: e.target.value as "PRESENT"|"ABSENT"|"MISSING" })} className="mb-1 w-full rounded border px-2 py-1"><option value="PRESENT">Present</option><option value="ABSENT">Absent</option><option value="MISSING">Missing</option></select>{cell.state === "PRESENT" && (component.is_developmental ? <input disabled={!editable} value={cell.development} maxLength={60} onChange={(e) => updateCell(student.id,component.id,{development:e.target.value})} placeholder="Rating" className="w-full rounded border px-2 py-1"/> : <input disabled={!editable} type="number" min={0} max={component.maximum_score} step={1/10**component.precision_digits} value={cell.score} onChange={(e) => updateCell(student.id,component.id,{score:e.target.value})} className="w-full rounded border px-2 py-1"/>)}</td>; })}<td className="p-3 font-semibold">{total?.total?.toFixed(2) ?? "—"}</td><td className="p-3">{total?.position ?? "—"}</td><td className="p-3">{grade?.grade_code ?? "—"}</td></tr>; })}</tbody></table></div>
      {batch && <div className="flex flex-wrap items-end gap-2 border-t p-4 print:hidden"><label className="min-w-60 flex-1 text-xs font-semibold text-slate-600">Workflow note<input value={note} onChange={(e) => setNote(e.target.value)} maxLength={2000} className="mt-1 w-full rounded-lg border px-3 py-2" placeholder="Required when requesting corrections"/></label>{canReview && batch.status === "SUBMITTED" && <button onClick={() => send("REVIEW")} className="rounded-lg border px-3 py-2 text-xs font-semibold">Review submission</button>}{canPublish && batch.status === "REVIEWED" && <button onClick={() => send("APPROVE")} className="rounded-lg bg-upwa-blue-700 px-3 py-2 text-xs font-semibold text-white">Head / Principal approval</button>}{canPublish && batch.status === "APPROVED" && <button onClick={() => send("PUBLISH")} className="rounded-lg bg-upwa-green-700 px-3 py-2 text-xs font-semibold text-white">Publish approved results</button>}{canReview && ["SUBMITTED","REVIEWED","APPROVED","PUBLISHED"].includes(batch.status) && <button onClick={() => send("REQUEST_CORRECTION")} className="rounded-lg border border-upwa-orange-300 px-3 py-2 text-xs font-semibold text-upwa-orange-800">Request correction</button>}{canPublish && batch.status === "CORRECTION_REQUESTED" && <button onClick={() => send("APPROVE_CORRECTION")} className="rounded-lg bg-upwa-orange-600 px-3 py-2 text-xs font-semibold text-white">Approve correction window</button>}</div>}</section>}</div>;
}

export function ResultsCentre({ division, canIssue }: { division: string; canIssue: boolean }) {
  const [students, setStudents] = useState<Pupil[]>([]); const [sessions, setSessions] = useState<Pick[]>([]); const [terms, setTerms] = useState<(Pick & { session_id: string })[]>([]);
  const [studentId, setStudentId] = useState(""); const [sessionId, setSessionId] = useState(""); const [termId, setTermId] = useState("");
  const [scores, setScores] = useState<{ id: string; subject_id: string; session_id: string; term_id: string; numeric_score: number | null; developmental_level: string | null; score_state: string; subjects: { name: string } | null; assessment_components: { label: string; maximum_score: number; weight: number; counts_toward_total: boolean } | null }[]>([]);
  const [appraisals, setAppraisals] = useState<{ id: string; appraisal_key: string; rating: string; teacher_remark: string | null; session_id: string; term_id: string }[]>([]);
  const [reports, setReports] = useState<{ document_reference: string; version: number; status: string; issued_at: string }[]>([]); const [invoices,setInvoices]=useState<{id:string;invoice_number:string;total_amount:number;amount_paid:number;status:string;due_date:string|null;session_id:string;term_id:string}[]>([]); const [error,setError]=useState(""); const [busy,setBusy]=useState(false); const [notice,setNotice]=useState(""); const [bankInstruction,setBankInstruction]=useState<any>(null); const [installment,setInstallment]=useState("");
  const load = useCallback(async (child = studentId, session = sessionId, term = termId) => {
    const url = new URLSearchParams({ division }); if (child) url.set("studentId",child); if(session) url.set("sessionId",session); if(term) url.set("termId",term);
    const response=await fetch(`/api/portal/results?${url}`,{cache:"no-store"}); const data=await response.json(); if(!response.ok){setError(data.error??"Results unavailable.");return;}
    setStudents(data.students??[]); setSessions(data.sessions??[]); setTerms(data.terms??[]); setScores(data.scores??[]); setAppraisals(data.appraisals??[]); setReports(data.issuedReports??[]); setInvoices(data.invoices??[]);
    if (!session && data.sessions?.length) setSessionId(data.sessions.find((s: Pick & {is_current?:boolean})=>s.is_current)?.id ?? data.sessions[0].id);
    if (session && !term && data.terms?.filter((t: {session_id:string})=>t.session_id===session).length) { const choices=data.terms.filter((t: {session_id:string})=>t.session_id===session); setTermId(choices.find((t: Pick & {is_current?:boolean})=>t.is_current)?.id ?? choices[0].id); }
  },[division,studentId,sessionId,termId]);
  useEffect(()=>{load("","","");},[division]);
  useEffect(()=>{if(studentId) load(studentId,sessionId,termId);},[studentId,sessionId,termId]);
  const selected = students.find((s)=>s.id===studentId);
  const subjectRows = useMemo(()=>{
    const groups = new Map<string,{name:string;rows:typeof scores;sum:number;weight:number}>();
    for(const row of scores){const name=row.subjects?.name??"Subject";const item=groups.get(row.subject_id)??{name,rows:[],sum:0,weight:0}; if(row.assessment_components?.counts_toward_total && row.score_state==="PRESENT" && row.numeric_score!=null){item.sum+=Number(row.numeric_score)/Number(row.assessment_components.maximum_score)*Number(row.assessment_components.weight);item.weight+=Number(row.assessment_components.weight);} item.rows.push(row);groups.set(row.subject_id,item);}
    return Array.from(groups.values()).map((item)=>({...item,percentage:item.weight?Math.round(item.sum/item.weight*10000)/100:null}));
  },[scores]);
  async function issueReport(){if(!selected||!sessionId||!termId)return;setBusy(true);setError("");const response=await fetch("/api/portal/results",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"ISSUE_REPORT",division,studentId,sessionId,termId})});const data=await response.json();setBusy(false);if(!response.ok){setError(data.error??"Could not issue report.");return;}setNotice(`Issued report version ${data.version}.`);window.open(`/portal/results/report/${encodeURIComponent(data.reference)}?division=${encodeURIComponent(division)}`,"_blank","noopener,noreferrer");await load(studentId,sessionId,termId);}
  async function requestBankInstruction(invoiceId:string){setBusy(true);setError("");setBankInstruction(null);const response=await fetch("/api/portal/payments/bank-transfer",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({division,invoiceId,amount:installment?Number(installment):undefined})});const data=await response.json();setBusy(false);if(!response.ok){setError(data.error??"U&C bank instructions unavailable.");return;}setBankInstruction(data.instruction);setNotice("Use this unique reference for a transfer or counter deposit at U&C Microfinance Bank or another bank. Upload the receipt; finance must independently verify it.");}
  async function uploadTransferEvidence(file:File|null){if(!bankInstruction||!file)return;setBusy(true);setError("");const form=new FormData();form.set("evidence",file);const response=await fetch(`/api/portal/payments/${encodeURIComponent(bankInstruction.payment_id)}/evidence?division=${encodeURIComponent(division)}`,{method:"POST",body:form});const data=await response.json();setBusy(false);if(!response.ok){setError(data.error??"Transfer receipt could not be uploaded.");return;}setNotice("Private evidence uploaded. The school will verify the U&C bank settlement before crediting your invoice.");}
  return <section className="space-y-4"><header className="rounded-2xl border border-slate-200 bg-white p-5"><h1 className="text-lg font-bold text-upwa-navy">Secure Parent Result Centre</h1><p className="mt-1 text-sm text-slate-600">Only children linked to your signed-in account are listed. Only approved and published results appear here.</p><div className="mt-4 grid gap-3 sm:grid-cols-3"><label className="text-xs font-semibold text-slate-600">Child<select value={studentId} onChange={(e)=>{setStudentId(e.target.value);setScores([]);}} className="mt-1 w-full rounded-lg border px-3 py-2 text-sm"><option value="">Select linked child</option>{students.map((s)=><option key={s.id} value={s.id}>{s.first_name} {s.last_name} · {s.admission_number}</option>)}</select></label><label className="text-xs font-semibold text-slate-600">Session<select value={sessionId} onChange={(e)=>{setSessionId(e.target.value);setTermId("");}} className="mt-1 w-full rounded-lg border px-3 py-2 text-sm"><option value="">Select session</option>{sessions.map((s)=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label className="text-xs font-semibold text-slate-600">Term<select value={termId} onChange={(e)=>setTermId(e.target.value)} className="mt-1 w-full rounded-lg border px-3 py-2 text-sm"><option value="">Select term</option>{terms.filter((t)=>t.session_id===sessionId).map((t)=><option key={t.id} value={t.id}>{t.name}</option>)}</select></label></div>{error&&<p role="alert" className="mt-3 text-sm text-rose-700">{error}</p>}{notice&&<p role="status" className="mt-3 text-sm text-upwa-green-800">{notice}</p>}</header>{selected&&sessionId&&termId&&<><section className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-bold text-upwa-navy">Published subject results</h2><p className="text-xs text-slate-500">{selected.first_name} {selected.last_name} · {selected.admission_number}</p></div>{canIssue&&<button disabled={busy||scores.length===0} onClick={issueReport} className="rounded-lg bg-upwa-blue-700 px-4 py-2 text-xs font-semibold text-white disabled:opacity-50">{busy?"Issuing…":"Issue signed report card"}</button>}</div>{subjectRows.length===0?<p className="mt-4 text-sm text-slate-500">No results have been published for this period.</p>:<div className="mt-4 overflow-x-auto"><table className="w-full text-left text-sm"><thead className="bg-slate-50 text-xs"><tr><th className="p-3">Subject</th><th className="p-3">Assessment breakdown</th><th className="p-3">Weighted total / 100</th></tr></thead><tbody>{subjectRows.map((subject)=><tr key={subject.name} className="border-t"><td className="p-3 font-semibold">{subject.name}</td><td className="p-3">{subject.rows.map((row,index)=><span key={row.id}>{index>0?" · ":""}{row.assessment_components?.label}: {row.score_state==="ABSENT"?"Absent":row.score_state==="MISSING"?"Missing":row.developmental_level??row.numeric_score}</span>)}</td><td className="p-3 font-semibold">{subject.percentage?.toFixed(2)??"—"}</td></tr>)}</tbody></table></div>}</section>{appraisals.length>0&&<section className="rounded-2xl border border-slate-200 bg-white p-5"><h2 className="font-bold text-upwa-navy">Published behavioural appraisals</h2><div className="mt-3 divide-y">{appraisals.filter((a)=>a.session_id===sessionId&&a.term_id===termId).map((a)=><div key={a.id} className="py-3 text-sm"><b>{a.appraisal_key.replaceAll("_"," ")} · {a.rating.replaceAll("_"," ")}</b>{a.teacher_remark&&<p className="mt-1 text-slate-600">{a.teacher_remark}</p>}</div>)}</div></section>}<section className="rounded-2xl border border-slate-200 bg-white p-5"><h2 className="font-bold text-upwa-navy">Your child’s invoices</h2><p className="mt-1 text-xs text-slate-500">This private account view is only available to a linked guardian or authorised finance staff.</p>{invoices.filter((invoice)=>invoice.session_id===sessionId&&invoice.term_id===termId).length===0?<p className="mt-2 text-sm text-slate-500">No invoice is recorded for this child and period.</p>:invoices.filter((invoice)=>invoice.session_id===sessionId&&invoice.term_id===termId).map((invoice)=><div key={invoice.id} className="mt-3 flex flex-wrap items-center justify-between gap-3 border-t pt-3 text-sm"><span>{invoice.invoice_number} · {invoice.due_date?`Due ${invoice.due_date}`:"Due date not set"} · {invoice.status}</span><span className="font-semibold">{money(invoice.total_amount)} total</span>{Number(invoice.total_amount)>Number(invoice.amount_paid)&&<button disabled={busy} onClick={()=>requestBankInstruction(invoice.id)} className="rounded-lg bg-upwa-green-700 px-3 py-2 text-xs font-semibold text-white">U&amp;C bank transfer / counter instructions</button>}</div>)}<label className="mt-3 block text-xs">Optional installment in NGN; leave blank to request the full remaining balance<input type="number" min="100" step="1" value={installment} onChange={(e)=>setInstallment(e.target.value)} className="mt-1 w-full max-w-sm rounded border p-2"/></label>{bankInstruction&&<div className="mt-4 rounded-xl border border-upwa-green-200 bg-upwa-green-50 p-4 text-sm"><h3 className="font-bold text-upwa-green-950">U&amp;C Microfinance Bank payment instructions</h3><p className="mt-2">Bank: <b>{bankInstruction.bank_name}</b> · Account name: <b>{bankInstruction.account_name}</b></p><p>Account number: <b className="font-mono">{bankInstruction.account_number}</b>{bankInstruction.bank_branch?` · ${bankInstruction.bank_branch}`:""}</p><p>Amount: <b>{money(bankInstruction.amount)}</b> · Reference: <b className="font-mono">{bankInstruction.reference}</b></p><p className="mt-2 text-xs">Use the exact reference whether transferring from a banking app or paying over the counter. Do not hand cash to a staff member. Finance independently verifies U&amp;C settlement before crediting the invoice.</p><label className="mt-3 block text-xs font-semibold">Upload teller / transfer receipt (PDF, JPEG or PNG, max 5 MB)<input type="file" accept="application/pdf,image/jpeg,image/png" onChange={(e)=>uploadTransferEvidence(e.target.files?.[0]??null)} className="mt-1 block w-full"/></label></div>}</section><section className="rounded-2xl border border-slate-200 bg-white p-5"><h2 className="font-bold text-upwa-navy">Issued report cards</h2>{reports.filter((r)=>r.status==="VALID").length===0?<p className="mt-2 text-sm text-slate-500">No signed report card has been issued for this child yet.</p>:reports.filter((r)=>r.status==="VALID").map((r)=><a key={r.document_reference} href={`/portal/results/report/${encodeURIComponent(r.document_reference)}?division=${encodeURIComponent(division)}`} className="mt-2 block text-sm font-semibold text-upwa-blue-800 underline">Version {r.version} · {new Date(r.issued_at).toLocaleDateString()} · {r.document_reference}</a>)}</section></>}</section>;
}

export function FinanceWorkspace({ division, permissions }: { division: string; permissions: string[] }) {
  const [data,setData]=useState<any>(null); const [filters,setFilters]=useState<any>(null); const [error,setError]=useState(""); const [notice,setNotice]=useState(""); const [busy,setBusy]=useState(false);
  const [studentId,setStudentId]=useState(""); const [classId,setClassId]=useState(""); const [sessionId,setSessionId]=useState(""); const [termId,setTermId]=useState("");
  const canManage=permissions.includes("finance.manage"); const canApprove=permissions.includes("finance.expense_approve");
  const load=useCallback(async()=>{const response=await fetch(`/api/portal/finance?division=${encodeURIComponent(division)}`,{cache:"no-store"});const result=await response.json();if(!response.ok){setError(result.error??"Finance data unavailable.");return;}setData(result);setFilters(result.filters);},[division]);
  useEffect(()=>{load();},[load]);
  async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);const action=String(form.get("action"));let payload:any={division,action};if(action==="SET_FEE")Object.assign(payload,{classId:classId||null,sessionId,termId,studentCategory:form.get("studentCategory"),code:form.get("code"),description:form.get("description"),amount:Number(form.get("amount")),dueOn:form.get("dueOn")||null});if(action==="GENERATE_INVOICE")Object.assign(payload,{studentId,sessionId,termId,dueOn:form.get("dueOn")||null});if(action==="SUBMIT_EXPENSE")Object.assign(payload,{category:form.get("category"),payee:form.get("payee"),description:form.get("description"),amount:Number(form.get("amount")),expenseDate:form.get("expenseDate")});setBusy(true);setError("");const response=await fetch("/api/portal/finance",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});const result=await response.json();setBusy(false);if(!response.ok){setError(result.error??"Finance update failed.");return;}setNotice(action==="GENERATE_INVOICE"?"Invoice generated from the approved fee schedule.":action==="SET_FEE"?"Fee schedule saved.":"Expense request submitted for independent approval.");event.currentTarget.reset();await load();}
  async function expenseDecision(expenseId:string,decision:string){const note=decision==="MARK_PAID"?window.prompt("Enter payment reference (required)"):null;if(decision==="MARK_PAID"&&!note)return;setBusy(true);const response=await fetch("/api/portal/finance",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"EXPENSE_DECISION",division,expenseId,decision,note})});const result=await response.json();setBusy(false);if(!response.ok)setError(result.error??"Expense decision failed.");else{setNotice(`Expense ${String(result.status).toLowerCase()}.`);await load();}}
  const s=data?.summary??{};
  return <div className="space-y-5"><header className="rounded-2xl border border-slate-200 bg-white p-5"><h1 className="text-lg font-bold text-upwa-navy">School financial tracker</h1><p className="mt-1 text-sm text-slate-600">Division-specific billing, verified collections and segregated expense approvals. Collection is calculated from verified payment transactions, not invoices issued. Reports are management information, not audited financial statements.</p>{error&&<p role="alert" className="mt-3 text-sm text-rose-700">{error}</p>}{notice&&<p role="status" className="mt-3 text-sm text-upwa-green-800">{notice}</p>}</header><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[["Fees billed",money(s.billed)],["Verified collected",money(s.collected)],["Unpaid balance",money(s.unpaid)],["Non-tuition income",money(s.nonTuitionIncome)],["Expenses approved",money(s.expensesApproved)],["Expenses paid",money(s.expensesPaid)],["Net cash movement",money(s.netCashMovement)],["Reconciled cash",s.reconciledCash==null?"Not reconciled":money(s.reconciledCash)]].map(([label,value])=><div key={label} className="rounded-xl border bg-white p-4"><p className="text-xs font-semibold uppercase text-slate-500">{label}</p><p className="mt-2 text-lg font-bold text-upwa-navy">{value}</p></div>)}</div>
    {canManage&&<BankAccountSettings division={division}/>}
    {canManage&&<BankTransferReview division={division}/>}
    {canManage&&filters&&<div className="grid gap-4 xl:grid-cols-2"><section className="rounded-2xl border bg-white p-5"><h2 className="font-bold text-upwa-navy">Configure fee schedule</h2><p className="mt-1 text-xs text-slate-500">Enter only amounts approved by school management.</p><form onSubmit={submit} className="mt-3 grid gap-3 sm:grid-cols-2"><input type="hidden" name="action" value="SET_FEE"/><label className="text-xs">Class (optional)<select value={classId} onChange={(e)=>setClassId(e.target.value)} className="mt-1 w-full rounded border p-2"><option value="">All classes</option>{filters.classes.map((x:Pick)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label className="text-xs">Student category<select name="studentCategory" className="mt-1 w-full rounded border p-2"><option>ANY</option><option>DAY</option><option>BOARDING</option></select></label><label className="text-xs">Session<select required value={sessionId} onChange={(e)=>{setSessionId(e.target.value);setTermId("")}} className="mt-1 w-full rounded border p-2"><option value="">Choose session</option>{filters.sessions.map((x:Pick)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label className="text-xs">Term<select required value={termId} onChange={(e)=>setTermId(e.target.value)} className="mt-1 w-full rounded border p-2"><option value="">Choose term</option>{filters.terms.filter((x:any)=>x.session_id===sessionId).map((x:Pick)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label className="text-xs">Fee code<input name="code" required placeholder="Approved code" className="mt-1 w-full rounded border p-2"/></label><label className="text-xs">Description<input name="description" required placeholder="Approved fee description" className="mt-1 w-full rounded border p-2"/></label><label className="text-xs">Amount (NGN)<input name="amount" required type="number" min="0" step="0.01" className="mt-1 w-full rounded border p-2"/></label><label className="text-xs">Due date<input name="dueOn" type="date" className="mt-1 w-full rounded border p-2"/></label><button disabled={busy} className="rounded-lg bg-upwa-blue-700 px-3 py-2 text-sm font-semibold text-white">Save fee schedule</button></form></section>
      <section className="rounded-2xl border bg-white p-5"><h2 className="font-bold text-upwa-navy">Generate invoice</h2><p className="mt-1 text-xs text-slate-500">Invoices are built from the active fee schedule; repeated billing for the same pupil and period is blocked.</p><form onSubmit={submit} className="mt-3 grid gap-3"><input type="hidden" name="action" value="GENERATE_INVOICE"/><label className="text-xs">Pupil<select required value={studentId} onChange={(e)=>setStudentId(e.target.value)} className="mt-1 w-full rounded border p-2"><option value="">Select pupil</option>{filters.students.map((x:any)=><option key={x.id} value={x.id}>{x.first_name} {x.last_name} · {x.admission_number}</option>)}</select></label><div className="grid gap-3 sm:grid-cols-2"><label className="text-xs">Session<select required value={sessionId} onChange={(e)=>{setSessionId(e.target.value);setTermId("")}} className="mt-1 w-full rounded border p-2"><option value="">Choose session</option>{filters.sessions.map((x:Pick)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label className="text-xs">Term<select required value={termId} onChange={(e)=>setTermId(e.target.value)} className="mt-1 w-full rounded border p-2"><option value="">Choose term</option>{filters.terms.filter((x:any)=>x.session_id===sessionId).map((x:Pick)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label></div><label className="text-xs">Due date<input name="dueOn" type="date" className="mt-1 w-full rounded border p-2"/></label><button disabled={busy} className="rounded-lg bg-upwa-green-700 px-3 py-2 text-sm font-semibold text-white">Generate invoice</button></form></section></div>}
    {canManage&&<section className="rounded-2xl border bg-white p-5"><h2 className="font-bold text-upwa-navy">Submit an expense request</h2><p className="mt-1 text-xs text-slate-500">Requests require approval by a different authorised person. Do not mark an expense paid without its payment reference.</p><form onSubmit={submit} className="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><input type="hidden" name="action" value="SUBMIT_EXPENSE"/><label className="text-xs">Category<select name="category" className="mt-1 w-full rounded border p-2">{["PAYROLL","DIESEL","UTILITIES","TEACHING_MATERIALS","STATIONERY","MAINTENANCE","REPAIRS","REMITTANCES","OTHER"].map((x)=><option key={x}>{x}</option>)}</select></label><label className="text-xs">Payee<input name="payee" required className="mt-1 w-full rounded border p-2"/></label><label className="text-xs">Amount<input name="amount" required type="number" min="0.01" step="0.01" className="mt-1 w-full rounded border p-2"/></label><label className="text-xs">Date<input name="expenseDate" required type="date" className="mt-1 w-full rounded border p-2"/></label><label className="text-xs sm:col-span-2">Description<input name="description" required minLength={5} className="mt-1 w-full rounded border p-2"/></label><button disabled={busy} className="self-end rounded-lg bg-upwa-blue-700 px-3 py-2 text-sm font-semibold text-white">Submit for approval</button></form></section>}
    <section className="grid gap-4 xl:grid-cols-2"><div className="rounded-2xl border bg-white p-5"><h2 className="font-bold text-upwa-navy">Recent invoices</h2><div className="mt-3 space-y-2">{(data?.invoices??[]).length===0?<p className="text-sm text-slate-500">No invoices recorded.</p>:(data.invoices as any[]).slice(0,30).map((invoice)=><div key={invoice.id} className="flex flex-wrap justify-between gap-2 border-b py-2 text-xs"><span>{invoice.invoice_number} · {invoice.student_category} · due {invoice.due_date??"not set"}</span><b>{money(invoice.total_amount)} · {invoice.status}</b></div>)}</div></div><div className="rounded-2xl border bg-white p-5"><h2 className="font-bold text-upwa-navy">Expense approvals</h2><div className="mt-3 space-y-2">{(data?.expenses??[]).length===0?<p className="text-sm text-slate-500">No expense requests.</p>:(data.expenses as any[]).slice(0,30).map((expense)=><div key={expense.id} className="flex flex-wrap items-center justify-between gap-2 border-b py-2 text-xs"><span>{expense.category} · {expense.payee} · {expense.expense_date}<b className="block">{money(expense.amount)} · {expense.status}</b></span>{canApprove&&expense.status==="SUBMITTED"&&<span className="flex gap-2"><button disabled={busy} onClick={()=>expenseDecision(expense.id,"APPROVE")} className="rounded border border-upwa-green-300 px-2 py-1 text-upwa-green-800">Approve</button><button disabled={busy} onClick={()=>expenseDecision(expense.id,"REJECT")} className="rounded border border-rose-200 px-2 py-1 text-rose-700">Reject</button></span>}{canApprove&&expense.status==="APPROVED"&&<button disabled={busy} onClick={()=>expenseDecision(expense.id,"MARK_PAID")} className="rounded border px-2 py-1">Record paid</button>}</div>)}</div></div></section></div>;
}

export function ExecutiveConsole({ division }: { division: string }) {
  const [data,setData]=useState<any>(null); const [error,setError]=useState("");
  useEffect(()=>{fetch(`/api/portal/executive?division=${encodeURIComponent(division)}`,{cache:"no-store"}).then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.error??"Command console unavailable.");setData(d);}).catch(e=>setError(e instanceof Error?e.message:"Could not load executive console."));},[division]);
  if(error)return <p role="alert" className="rounded-xl bg-rose-50 p-4 text-rose-800">{error}</p>;
  if(!data)return <p className="rounded-xl bg-white p-5 text-slate-500">Loading reconciled executive indicators…</p>;
  const s=data.summary; const tiles:[[string,string,string],[string,string,string],[string,string,string],[string,string,string],[string,string,string],[string,string,string]]=[["Enrolment",Number(s.activeStudents??0).toLocaleString(),"Active pupil records"],["Staff",Number(s.staffCount??0).toLocaleString(),"Active staff profiles"],["Fees billed",money(s.billed),"Invoice totals"],["Verified collections",money(s.collected),`${s.collectionPercent}% of billed amount`],["Outstanding",money(s.unpaid),"Computed from verified allocations"],["Net cash movement",money(s.netCashMovement),"Verified collections less paid expenses"]];
  const pie=[{name:"Paid invoices",value:s.debtors?.paid??0},{name:"Part paid",value:s.debtors?.partial??0},{name:"Unpaid",value:s.debtors?.unpaid??0}]; const colors=["#17884a","#f0a51b","#cf3b43"];
  return <div className="space-y-5"><header className="rounded-2xl border border-upwa-blue-100 bg-white p-5"><p className="text-xs font-semibold uppercase tracking-widest text-upwa-orange-700">UPWA Executive Command Console</p><h1 className="mt-1 text-xl font-bold text-upwa-navy">{division==="ALL"?"Consolidated view":"Division performance"}</h1><p className="mt-1 text-sm text-slate-600">Live role-scoped indicators · refreshed {new Date(data.generatedAt).toLocaleString()}</p></header><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{tiles.map(([label,value,note])=><article key={label} className="rounded-2xl border border-slate-200 bg-white p-5"><p className="text-xs font-semibold uppercase tracking-wide text-slate-500">{label}</p><p className="mt-2 text-2xl font-bold text-upwa-navy">{value}</p><p className="mt-1 text-xs text-slate-500">{note}</p></article>)}</div><div className="grid gap-4 xl:grid-cols-2"><section className="rounded-2xl border bg-white p-5"><h2 className="font-bold text-upwa-navy">Verified collections vs paid expenses</h2><div className="mt-3 h-72"><ResponsiveContainer width="100%" height="100%"><BarChart data={data.trend}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="month" tickFormatter={shortMonth}/><YAxis tickFormatter={(n)=>`${Math.round(n/1000)}k`}/><Tooltip formatter={(value)=>money(value)}/><Legend/><Bar dataKey="collected" name="Collected" fill="#1485b5" radius={[4,4,0,0]}/><Bar dataKey="expenses" name="Paid expenses" fill="#e99d17" radius={[4,4,0,0]}/></BarChart></ResponsiveContainer></div></section><section className="rounded-2xl border bg-white p-5"><h2 className="font-bold text-upwa-navy">Invoice debtor distribution</h2><div className="mt-3 h-72"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={pie} dataKey="value" nameKey="name" outerRadius={95} label>{pie.map((entry,index)=><Cell key={entry.name} fill={colors[index]}/>)}</Pie><Tooltip/><Legend/></PieChart></ResponsiveContainer></div></section></div><div className="grid gap-4 xl:grid-cols-2"><section className="rounded-2xl border bg-white p-5"><h2 className="font-bold text-upwa-navy">Division comparison · six months</h2><div className="mt-3 h-64"><ResponsiveContainer width="100%" height="100%"><BarChart data={data.divisionComparison}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name"/><YAxis/><Tooltip formatter={(v)=>money(v)}/><Legend/><Bar dataKey="billed" fill="#7087a0"/><Bar dataKey="collected" fill="#168849"/></BarChart></ResponsiveContainer></div></section><section className="rounded-2xl border bg-white p-5"><h2 className="font-bold text-upwa-navy">Recent activity</h2><p className="mt-1 text-xs text-slate-500">Restricted operational events; no pupil identities or private payment details are shown.</p><ul className="mt-3 max-h-60 divide-y overflow-auto">{data.activity.length===0?<li className="py-3 text-sm text-slate-500">No recent activity recorded.</li>:data.activity.map((event:any)=><li key={event.id} className="py-2 text-xs"><b>{String(event.action).replaceAll("_"," ")}</b><span className="block text-slate-500">{event.actor_label} · {new Date(event.created_at).toLocaleString()}</span></li>)}</ul></section></div><ul className="rounded-xl bg-slate-50 p-4 text-xs text-slate-500">{data.caveats.map((item:string)=><li key={item} className="list-disc pl-2">{item}</li>)}</ul></div>;
}

type MorningReport = {
  period?: { from: string; to: string };
  received?: number;
  expensesApproved?: number;
  expensesPaid?: number;
  arrears?: number;
  feeCollectionByDivision?: { division: string; received: number }[];
  attendance?: { present: number; absent: number; late: number; excused: number; rate: number | null };
  admissions?: { received: number; pending: number };
  pendingExecutiveApprovals?: { resultBatches: number; expenses: number; feeAdjustments: number };
  operationalFlags?: string[];
  upcomingMilestones?: { type: string; title: string; date: string }[];
};

export function MorningBrief({ division }: { division: string }) {
  const [report, setReport] = useState<MorningReport | null>(null);
  const [frequency, setFrequency] = useState<"DAILY" | "WEEKLY" | "MONTHLY">("WEEKLY");
  const [notice, setNotice] = useState("");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [scheduleActive, setScheduleActive] = useState(true);
  const load = useCallback(async () => {
    const response = await fetch(`/api/portal/morning-brief?division=${encodeURIComponent(division)}`, { cache: "no-store" });
    const data = await response.json();
    if (!response.ok) { setError(data.error ?? "Morning brief unavailable."); return; }
    setReport(data.report ?? {});
    const schedule = (data.schedules ?? []).find((row: { division_id: string | null }) => row.division_id === data.divisionId);
    if (schedule) { setFrequency(schedule.frequency); setScheduleActive(schedule.is_active); }
  }, [division]);
  useEffect(() => { load(); }, [load]);
  async function saveSchedule() {
    setBusy(true); setNotice(""); setError("");
    const response = await fetch("/api/portal/morning-brief", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ division, frequency, active: scheduleActive }) });
    const data = await response.json(); setBusy(false);
    if (!response.ok) { setError(data.error ?? "Schedule could not be saved."); return; }
    setNotice(data.message ?? "Schedule saved."); await load();
  }
  if (!report) return <section className="mt-6 rounded-2xl border bg-white p-5"><h2 className="font-bold text-upwa-navy">President’s Morning Brief</h2><p className="mt-2 text-sm text-slate-500">Loading authorised executive indicators…</p>{error && <p role="alert" className="mt-2 text-sm text-rose-700">{error}</p>}</section>;
  const cards: [string, unknown][] = [["Received", report.received], ["Expenses approved", report.expensesApproved], ["Expenses paid", report.expensesPaid], ["Current arrears", report.arrears]];
  const pending = report.pendingExecutiveApprovals ?? { resultBatches: 0, expenses: 0, feeAdjustments: 0 };
  return <section className="mt-6 rounded-2xl border border-slate-200 bg-white p-5 print:border-0 print:shadow-none">
    <header className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-semibold uppercase tracking-widest text-upwa-blue-700">Weekly default digest · {report.period?.from} to {report.period?.to}</p><h2 className="mt-1 text-xl font-bold text-upwa-navy">President’s Morning Brief</h2><p className="mt-1 text-xs text-slate-500">Database-derived indicators. No student names, health details or donor identities are included.</p></div><button onClick={() => window.print()} className="rounded-lg border px-3 py-2 text-sm font-semibold print:hidden">Print / Save PDF</button></header>
    <div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{cards.map(([label, value]) => <div key={label} className="rounded-xl bg-slate-50 p-4"><p className="text-xs uppercase text-slate-500">{label}</p><p className="mt-1 font-bold text-upwa-navy">{money(value)}</p></div>)}</div>
    <div className="mt-4 grid gap-4 lg:grid-cols-2"><section className="rounded-xl border p-4"><h3 className="font-semibold">Fee collection by division</h3>{(report.feeCollectionByDivision ?? []).map((item) => <p key={item.division} className="flex justify-between gap-2 border-b py-2 text-sm"><span>{item.division}</span><b>{money(item.received)}</b></p>)}</section><section className="rounded-xl border p-4"><h3 className="font-semibold">Attendance and admissions</h3><p className="mt-2 text-sm">Attendance rate: <b>{report.attendance?.rate == null ? "No attendance recorded" : `${report.attendance.rate.toFixed(2)}%`}</b></p><p className="mt-1 text-sm">{report.admissions?.received ?? 0} new applications · {report.admissions?.pending ?? 0} pending</p><p className="mt-1 text-sm">Pending approvals: {pending.resultBatches} result batches · {pending.expenses} expenses · {pending.feeAdjustments} fee adjustments</p></section></div>
    {(report.operationalFlags?.length ?? 0) > 0 && <section className="mt-4 rounded-xl border border-amber-200 bg-amber-50 p-4"><h3 className="font-semibold text-amber-950">Operational flags</h3><ul className="mt-2 list-disc pl-5 text-sm text-amber-900">{report.operationalFlags?.map((flag) => <li key={flag}>{flag}</li>)}</ul></section>}
    {(report.upcomingMilestones?.length ?? 0) > 0 && <section className="mt-4 rounded-xl border p-4"><h3 className="font-semibold">Upcoming milestones</h3><ul className="mt-2 space-y-1 text-sm">{report.upcomingMilestones?.map((item, i) => <li key={`${item.type}-${item.title}-${i}`}>{item.date}: {item.title}</li>)}</ul></section>}
    <div className="mt-4 flex flex-wrap items-end gap-3 border-t pt-4 print:hidden"><label className="text-xs font-semibold">Automated delivery<select value={frequency} onChange={(e) => setFrequency(e.target.value as typeof frequency)} className="mt-1 block rounded-lg border px-3 py-2"><option value="DAILY">Daily</option><option value="WEEKLY">Weekly (default)</option><option value="MONTHLY">Monthly</option></select></label><label className="flex items-center gap-2 text-xs"><input type="checkbox" checked={scheduleActive} onChange={(e) => setScheduleActive(e.target.checked)} />Email my verified account only</label><button disabled={busy} onClick={saveSchedule} className="rounded-lg bg-upwa-blue-700 px-4 py-2 text-sm font-semibold text-white disabled:opacity-50">{busy ? "Saving…" : "Save schedule"}</button></div>
    {error && <p role="alert" className="mt-2 text-sm text-rose-700">{error}</p>}{notice && <p role="status" className="mt-2 text-sm text-upwa-green-800">{notice}</p>}
    <p className="mt-3 text-[11px] text-slate-500">Management information, not audited accounts or an uptime guarantee. Email delivery requires verified account email, scheduler and provider configuration.</p>
  </section>;
}

export function BankAccountSettings({ division }: { division: string }) {
  const [accounts,setAccounts]=useState<any[]>([]);const [error,setError]=useState("");const [message,setMessage]=useState("");const [busy,setBusy]=useState(false);
  const load=useCallback(async()=>{const response=await fetch(`/api/portal/finance/bank-accounts?division=${encodeURIComponent(division)}`,{cache:"no-store"});const data=await response.json();if(!response.ok){setError(data.error??"Bank details unavailable.");return;}setAccounts(data.accounts??[]);},[division]);
  useEffect(()=>{load();},[load]);
  async function create(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);setError("");const form=new FormData(event.currentTarget);const response=await fetch("/api/portal/finance/bank-accounts",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"CREATE",division,accountName:form.get("accountName"),accountNumber:form.get("accountNumber"),branch:form.get("branch"),purpose:form.get("purpose")})});const data=await response.json();setBusy(false);if(!response.ok){setError(data.error??"Could not save U&C account details.");return;}setMessage("Account submitted. A different finance user must approve it before parents see the instructions.");event.currentTarget.reset();await load();}
  async function approve(id:string,active:boolean){setBusy(true);const response=await fetch("/api/portal/finance/bank-accounts",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"APPROVE",division,accountId:id,active})});const data=await response.json();setBusy(false);if(!response.ok){setError(data.error??"Approval failed.");return;}setMessage(`U&C account ${String(data.status).toLowerCase()}.`);await load();}
  return <section className="rounded-2xl border bg-white p-5"><h2 className="font-bold text-upwa-navy">U&amp;C Microfinance Bank collection instructions</h2><p className="mt-1 text-sm text-slate-600">No account number is prefilled. Enter only an account verified by UPWA; a second authorised finance user must approve it before guardians can see it.</p>{accounts.map((account)=><div key={account.id} className="mt-3 flex flex-wrap items-center justify-between gap-3 border-t pt-3 text-sm"><span>{account.institution_name} · {account.account_name} · ••••{account.account_number.slice(-4)} · {account.account_purpose} · {account.is_active?"Active":"Awaiting approval"}</span>{!account.is_active&&<button disabled={busy||account.created_by===account.approved_by} onClick={()=>approve(account.id,true)} className="rounded border px-3 py-1.5 text-xs font-semibold">Approve account</button>}{account.is_active&&<button disabled={busy} onClick={()=>approve(account.id,false)} className="rounded border border-rose-200 px-3 py-1.5 text-xs text-rose-700">Deactivate</button>}</div>)}<form onSubmit={create} className="mt-4 grid gap-3 border-t pt-4 sm:grid-cols-2"><label className="text-xs">Account name<input name="accountName" required minLength={3} maxLength={160} className="mt-1 w-full rounded border p-2"/></label><label className="text-xs">U&amp;C account number<input name="accountNumber" required pattern="[0-9]{8,20}" inputMode="numeric" className="mt-1 w-full rounded border p-2"/></label><label className="text-xs">Branch (optional)<input name="branch" maxLength={120} className="mt-1 w-full rounded border p-2"/></label><label className="text-xs">Purpose<select name="purpose" className="mt-1 w-full rounded border p-2"><option value="SCHOOL_FEES">School fees</option><option value="DONATIONS">Donations</option><option value="OPERATIONS">Operations</option></select></label><button disabled={busy} className="w-fit rounded-lg bg-upwa-blue-700 px-3 py-2 text-sm font-semibold text-white">Submit verified account details</button></form>{error&&<p role="alert" className="mt-3 text-sm text-rose-700">{error}</p>}{message&&<p role="status" className="mt-3 text-sm text-upwa-green-800">{message}</p>}</section>;
}

export function BankTransferReview({division}:{division:string}){
  const [items,setItems]=useState<any[]>([]);const [evidence,setEvidence]=useState<any[]>([]);const [error,setError]=useState("");const [busy,setBusy]=useState(false);
  const load=useCallback(async()=>{const response=await fetch(`/api/portal/payments/review?division=${encodeURIComponent(division)}`,{cache:"no-store"});const data=await response.json();if(!response.ok){setError(data.error??"Transfer queue unavailable.");return;}setItems(data.payments??[]);setEvidence(data.evidence??[]);},[division]);useEffect(()=>{load();},[load]);
  async function decide(paymentId:string,decision:"VERIFY"|"REJECT"){const note=decision==="REJECT"?window.prompt("Reason for rejecting the evidence (optional)"):window.prompt("Enter the unique transaction reference shown on the U&C bank statement (required)");if(note===null||(decision==="VERIFY"&&note.trim().length<4))return;setBusy(true);const response=await fetch("/api/portal/payments/review",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({division,paymentId,decision,note})});const data=await response.json();setBusy(false);if(!response.ok){setError(data.error??"Transfer review failed.");return;}setError("");await load();}
  return <section className="rounded-2xl border bg-white p-5"><h2 className="font-bold text-upwa-navy">U&amp;C transfer / counter-deposit review</h2><p className="mt-1 text-xs text-slate-500">Only verify after matching the unique reference, amount and settlement in the U&amp;C bank statement. Evidence is private. The submitter cannot verify their own payment.</p>{items.length===0?<p className="mt-3 text-sm text-slate-500">No pending transfer submissions.</p>:items.map((payment)=><div key={payment.id} className="mt-3 flex flex-wrap items-center justify-between gap-3 border-t pt-3 text-xs"><div><b>{payment.external_reference}</b><p>{money(payment.amount)} · {payment.status} · {new Date(payment.created_at).toLocaleString()}</p><p className="text-slate-500">Invoice {payment.metadata?.invoice_id??"not linked"} · Pupil record {payment.student_id}</p>{evidence.filter((row)=>row.payment_id===payment.id).map((row)=><a key={row.id} href={`/api/portal/payments/evidence/${encodeURIComponent(row.id)}?division=${encodeURIComponent(division)}`} target="_blank" rel="noreferrer" className="mt-1 inline-block underline">View private {row.mime_type} evidence</a>)}</div><div className="flex gap-2"><button disabled={busy||!evidence.some((row)=>row.payment_id===payment.id)} onClick={()=>decide(payment.id,"VERIFY")} className="rounded bg-upwa-green-700 px-3 py-2 font-semibold text-white disabled:opacity-50">Verify settlement</button><button disabled={busy} onClick={()=>decide(payment.id,"REJECT")} className="rounded border border-rose-200 px-3 py-2 text-rose-700">Reject</button></div></div>)}{error&&<p role="alert" className="mt-2 text-sm text-rose-700">{error}</p>}</section>;
}
